SELECT p.slug project,l.root_path,d.path,s.name,s.qualified_name,s.symbol_kind,s.line_number,d.freshness_status FROM code_symbols s JOIN source_documents d ON d.id=s.source_document_id JOIN repository_locations l ON l.id=d.repository_location_id JOIN projects p ON p.id=d.project_id WHERE ($2::text IS NULL OR p.slug=$2) AND d.is_current AND d.freshness_status='current' AND EXISTS (SELECT 1 FROM unnest($4::text[]) AS allowed(root_path) WHERE l.root_path=allowed.root_path) AND (s.name ILIKE '%' || $1 || '%' OR s.qualified_name ILIKE '%' || $1 || '%') ORDER BY (s.name ILIKE $1) DESC,s.qualified_name LIMIT $3
